func runChannelDeliveryInboundDispositionE2E(t *testing.T, backend, scenario string) {
	t.Helper()
	retainedInteraction := scenario == "ordered_input_restart" || scenario == "draft_chooser_restart"
	if retainedInteraction {
		scenario = strings.TrimSuffix(scenario, "_restart")
	}
	nativeInboxScenario := scenario == "inbox" || scenario == "inbox_loss" || scenario == "inbox_restart"
	isolateCLIAPIConfigEnv(t)
	configureStandingLifecycleCredentials(t)
	provider := &telegramapi.Double{}
	var commandApplyArrived <-chan struct{}
	var releaseCommandApply func()
	if scenario == "inbox_delayed_apply" {
		commandApplyArrived, releaseCommandApply = provider.PauseNextCommandApply()
	}
	telegram := httptest.NewServer(provider)
	t.Cleanup(telegram.Close)
	if releaseCommandApply != nil {
		t.Cleanup(releaseCommandApply)
	}
	sourceRoot := writeStandingTelegramServeFixture(t, telegram.URL)
	if scenario == "action_pages" {
		schemaPath := filepath.Join(sourceRoot, "telegram-ingress", "schema.yaml")
		raw, err := os.ReadFile(schemaPath)
		if err != nil {
			t.Fatal(err)
		}
		var extra strings.Builder
		for index := 1; index <= 9; index++ {
			fmt.Fprintf(&extra, "        choice%02d:\n          advances_to: done\n", index)
		}
		modified := strings.Replace(string(raw), "        retire:\n          advances_to: done", extra.String()+"        retire:\n          advances_to: done", 1)
		if modified == string(raw) {
			t.Fatal("standing Telegram fixture lacked the expected decision outcomes")
		}
		if err := os.WriteFile(schemaPath, []byte(modified), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	if scenario == "draft_chooser" || scenario == "quoted_two" {
		sourceRoot = writeMixedStandingTelegramServeFixture(t, telegram.URL)
	}
	if scenario == "required_input" || scenario == "invalid_input" || scenario == "ordered_input" || scenario == "edit_loss_resend" || scenario == "cancel_input" || scenario == "skip_input" || scenario == "draft_chooser" || scenario == "quoted_two" {
		flowNames := []string{"telegram-ingress"}
		if scenario == "draft_chooser" || scenario == "quoted_two" {
			flowNames = append(flowNames, "telegram-stopped")
		}
		for _, flowName := range flowNames {
			schemaPath := filepath.Join(sourceRoot, flowName, "schema.yaml")
			raw, err := os.ReadFile(schemaPath)
			if err != nil {
				t.Fatal(err)
			}
			inputType := "text"
			if scenario == "invalid_input" {
				inputType = "integer"
			}
			inputBlock := "reason: {type: " + inputType + ", required: true}\n"
			if scenario == "ordered_input" {
				inputBlock = "zeta: {type: integer, required: true}\nalpha: {type: boolean, required: true}\n"
			} else if scenario == "skip_input" {
				inputBlock = "reason: {type: text, required: false}\n"
			}
			var schema, input yaml.Node
			if err := yaml.Unmarshal(raw, &schema); err != nil {
				t.Fatal(err)
			}
			if err := yaml.Unmarshal([]byte(inputBlock), &input); err != nil {
				t.Fatal(err)
			}
			if len(schema.Content) != 1 || len(input.Content) != 1 {
				t.Fatal("standing Telegram fixture has invalid schema or input document")
			}
			outcome := schema.Content[0]
			for _, key := range []string{"stages", "active", "gate", "outcomes", "retire"} {
				var next *yaml.Node
				if outcome.Kind == yaml.MappingNode {
					for index := 0; index+1 < len(outcome.Content); index += 2 {
						if outcome.Content[index].Value == key {
							next = outcome.Content[index+1]
							break
						}
					}
				}
				if next == nil {
					t.Fatalf("standing Telegram fixture missing %q gate path", key)
				}
				outcome = next
			}
			if outcome.Kind != yaml.MappingNode {
				t.Fatal("standing Telegram retire outcome is not a mapping")
			}
			for index := 0; index+1 < len(outcome.Content); index += 2 {
				if outcome.Content[index].Value == "input" {
					t.Fatal("standing Telegram retire outcome already has input")
				}
			}
			outcome.Content = append(outcome.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "input"}, input.Content[0])
			modified, err := yaml.Marshal(&schema)
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(schemaPath, modified, 0o600); err != nil {
				t.Fatal(err)
			}
		}
	}
	publicListener := reserveChannelOnboardingListener(t)
	publicListen := publicListener.Addr().String()
	redirectExternalHosts(t, map[string]string{"hooks.channel-onboarding.test": "http://" + publicListen})
	var configPath, observerDSN string
	if backend == "postgres" {
		dsn, _, _ := testutil.StartPostgres(t)
		observerDSN = dsn
		configPath = writeChannelOnboardingPostgresRuntimeConfig(t, dsn)
	} else {
		sqlitePath := filepath.Join(t.TempDir(), "channel-inbound.sqlite")
		observerDSN = sqlitePath
		configPath = writeStoreBackendRuntimeConfigWithWorkspaceFields(t, "sqlite", sqlitePath, channelOnboardingHostWorkspaceFields())
	}
	enableChannelOnboardingRecoveryOnStartup(t, configPath)
	opts := cliapp.ServeOptions{SourceRoot: sourceRoot, PlatformSpecPath: defaultPlatformSpecPath, ConfigPath: configPath, APIListenAddr: "127.0.0.1:0", MCPListenAddr: "127.0.0.1:0", PublicWebhookBaseURL: "https://hooks.channel-onboarding.test", PublicWebhookListen: publicListen, PublicWebhookListener: publicListener, SelfCheck: true, AbandonActiveRuns: true, WorkspaceBackend: "host", WorkspaceBackendSet: true, TestLLMRuntime: telegramPhraseBotLLMRuntime{}, StoreMode: backend, StoreModeSet: true}
	if scenario == "notice" || scenario == "notice_ack" || scenario == "shared_audience" || scenario == "summary_open" || scenario == "summary_open_many" || scenario == "delivery_loss_resend" || scenario == "notice_uncertainty_readback" {
		opts.TestLLMRuntime = telegramNoticeLLMRuntime{}
	} else if scenario == "view_full" {
		opts.TestLLMRuntime = telegramLongNoticeLLMRuntime{}
	}
	observation := &channelReconcileObservation{}
	if scenario == "delivery_loss_resend" || scenario == "edit_loss_resend" || scenario == "notice_uncertainty_readback" {
		observation.configure(&opts)
	}
	process := startServeRuntimeTestProcess(t, opts)
	t.Cleanup(func() {
		_ = process.stop()
	})
	process.waitForReadyLine()
	endpoint := "http://" + serveRuntimeAPIListenerFromOutput(t, process.outputString())
	if scenario == "summary_open" || scenario == "summary_open_many" || scenario == "notice_uncertainty_readback" {
		rpcEndpoint := endpoint + "/v1/rpc"
		var identity apiv1.RuntimeIdentityResult
		requireServedJSONRPCResult(t, rpcEndpoint, "runtime.identity", map[string]any{}, &identity)
		if len(identity.SourceArtifacts) != 1 {
			t.Fatalf("preconnection runtime sources = %+v, want one", identity.SourceArtifacts)
		}
		count := 1
		if scenario == "summary_open_many" {
			count = 7
		}
		for index := 0; index < count; index++ {
			var published map[string]any
			requireServedJSONRPCResult(t, rpcEndpoint, "event.publish", map[string]any{"bundle_hash": identity.SourceArtifacts[0].BundleHash, "event_name": "inbound.telegram.text_message", "idempotency_key": fmt.Sprintf("preconnection-notice-%d", index), "payload": map[string]any{"text": "ordinary business text", "external_account_reference": "7000", "conversation_reference": "1001", "conversation_scope": "direct", "provider_message_reference": 9100 + index}}, &published)
			deadline := time.Now().Add(15 * time.Second)
			for {
				var listed map[string]any
				requireServedJSONRPCResult(t, rpcEndpoint, "mailbox.list", map[string]any{"status": "pending"}, &listed)
				items, _ := listed["items"].([]any)
				notices := 0
				for _, raw := range items {
					item, _ := raw.(map[string]any)
					if item["kind"] == "notice" {
						notices++
					}
				}
				if notices >= index+1 {
					break
				}
				if time.Now().After(deadline) {
					t.Fatalf("preconnection notice %d did not commit: %v", index+1, listed)
				}
				time.Sleep(20 * time.Millisecond)
			}
		}
	}
	if scenario == "inbox_install_loss" {
		provider.LoseNextCommandWriteAcknowledgment()
	} else if scenario == "inbox_readback_failure" {
		provider.FailCommandReadbackAfterWrite()
	} else if scenario == "inbox_foreign_commands" {
		if err := provider.SeedCommands("bot-token", map[string]any{"type": "chat", "chat_id": "1001"}, "", []map[string]any{{"command": "foreign", "description": "Foreign owner"}}); err != nil {
			t.Fatal(err)
		}
	}
	chatID, chatType := int64(1001), "private"
	if scenario == "shared_audience" {
		chatID, chatType = -1001, "group"
	}
	runChannelOnboardingCLIJourney(t, configPath, endpoint, provider, "connect", "bot-token", chatID, chatType, 0)
	var preRestartDeliveries int
	if scenario == "inbox_restart" || scenario == "inbox_restart_mismatch" {
		deadline := time.Now().Add(15 * time.Second)
		for provider.Delivery(1) == nil {
			if time.Now().After(deadline) {
				t.Fatal("initial card was not delivered before served restart")
			}
			time.Sleep(20 * time.Millisecond)
		}
		time.Sleep(250 * time.Millisecond)
		_, preRestartDeliveries = provider.Counts()
		if code := process.stop(); code != 0 {
			t.Fatalf("first serve exited %d: %s", code, process.outputString())
		}
		if scenario == "inbox_restart_mismatch" {
			if err := provider.SeedCommands("bot-token", map[string]any{"type": "chat", "chat_id": "1001"}, "", []map[string]any{{"command": "foreign", "description": "Foreign owner"}}); err != nil {
				t.Fatal(err)
			}
		}
		process = startServeRuntimeTestProcess(t, opts)
		process.waitForReadyLine()
		endpoint = "http://" + serveRuntimeAPIListenerFromOutput(t, process.outputString())
		if scenario == "inbox_restart_mismatch" {
			time.Sleep(5500 * time.Millisecond)
			_, after := provider.Counts()
			if after != preRestartDeliveries || len(provider.CommandWrites()) != 1 {
				t.Fatalf("conflicting retired command was reused or overwritten: deliveries=%d before=%d writes=%v", after, preRestartDeliveries, provider.CommandWrites())
			}
			return
		}
	}
	if scenario == "shared_audience" {
		callbackURL, signing, _ := provider.Registration()
		proveChannelSharedAudience(t, provider, callbackURL, signing)
		return
	}
	if scenario == "inbox_delayed_apply" {
		select {
		case <-commandApplyArrived:
		case <-time.After(15 * time.Second):
			t.Fatal("native setting write did not launch")
		}
		var reconnect map[string]any
		requireServedJSONRPCResult(t, endpoint+"/v1/rpc", "channel.onboarding_start", map[string]any{"provider": "telegram", "verb": "reconnect", "save_proof": false}, &reconnect)
		operation, _ := reconnect["operation"].(map[string]any)
		if operation["phase"] != "awaiting_external_identity" {
			t.Fatalf("reconnect did not admit an independent ceremony: %v", reconnect)
		}
		if writes := provider.CommandWrites(); len(writes) != 0 {
			t.Fatalf("successor wrote over launched predecessor: %v", writes)
		}
		for index := 0; ; index++ {
			delivery := provider.Delivery(index)
			if delivery == nil {
				break
			}
			if strings.HasPrefix(fmt.Sprint(delivery["text"]), "Retire service") {
				t.Fatalf("card delivered before native setting write settled: %v", delivery)
			}
		}
		releaseCommandApply()
		deadline := time.Now().Add(15 * time.Second)
		for {
			writes := provider.CommandWrites()
			cardDelivered := false
			for index := 0; ; index++ {
				delivery := provider.Delivery(index)
				if delivery == nil {
					break
				}
				cardDelivered = cardDelivered || strings.HasPrefix(fmt.Sprint(delivery["text"]), "Retire service")
			}
			if len(writes) == 1 && cardDelivered {
				break
			}
			if time.Now().After(deadline) {
				t.Fatalf("delayed predecessor did not converge: writes=%v card=%v", writes, cardDelivered)
			}
			time.Sleep(20 * time.Millisecond)
		}
		return
	}
	if scenario == "inbox_install_loss" || scenario == "inbox_readback_failure" || scenario == "inbox_foreign_commands" {
		time.Sleep(5500 * time.Millisecond)
		wantWrites := 1
		if scenario == "inbox_foreign_commands" {
			wantWrites = 0
		}
		if writes := provider.CommandWrites(); len(writes) != wantWrites {
			t.Fatalf("non-usable native setting caused %d writes, want %d: %v", len(writes), wantWrites, writes)
		}
		if delivery := provider.Delivery(1); delivery != nil {
			reads, failures := provider.CommandReadbackCounts()
			t.Fatalf("non-usable native setting admitted channel delivery: %v; readbacks=%d failures=%d writes=%v", delivery, reads, failures, provider.CommandWrites())
		}
		return
	}
	if scenario == "summary_open" || scenario == "summary_open_many" {
		callbackURL, signing, _ := provider.Registration()
		count := 1
		if scenario == "summary_open_many" {
			count = 7
		}
		proveChannelBacklogSummaryOpenInbox(t, provider, callbackURL, signing, count)
		return
	}
	cardMessages := map[string]int{}
	if scenario == "draft_chooser" || scenario == "quoted_two" || scenario == "notice_uncertainty_readback" {
		db, err := sql.Open(backend, observerDSN)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() {
			_ = db.Close()
		})
		anchorReader := openChannelAnchorStorageAtLocation(t, backend, observerDSN)
		cardMessages["telegram-ingress"] = waitChannelCardMessageID(t, anchorReader, backend, "telegram-ingress")
		if scenario == "draft_chooser" || scenario == "quoted_two" {
			cardMessages["telegram-stopped"] = waitChannelCardMessageID(t, anchorReader, backend, "telegram-stopped")
			if cardMessages["telegram-ingress"] == cardMessages["telegram-stopped"] {
				t.Fatal("independent standing cards share one provider message")
			}
		}
	}
	inputText := "ordinary business text"
	if nativeInboxScenario {
		deadline := time.Now().Add(15 * time.Second)
		for {
			for _, write := range provider.CommandWrites() {
				scope, _ := write["scope"].(map[string]any)
				if scope["type"] != "chat" || fmt.Sprint(scope["chat_id"]) != "1001" {
					continue
				}
				commands, _ := write["commands"].([]map[string]any)
				if len(commands) == 1 {
					inputText = "/" + fmt.Sprint(commands[0]["command"])
					break
				}
			}
			if inputText != "ordinary business text" {
				break
			}
			if time.Now().After(deadline) {
				t.Fatalf("native Open inbox command was not installed: %v", provider.CommandWrites())
			}
			time.Sleep(20 * time.Millisecond)
		}
	}
	if scenario == "inbox_loss" {
		deadline := time.Now().Add(15 * time.Second)
		for provider.Delivery(1) == nil {
			if time.Now().After(deadline) {
				t.Fatal("initial card delivery did not settle before loss probe")
			}
			time.Sleep(20 * time.Millisecond)
		}
		time.Sleep(250 * time.Millisecond)
		provider.LoseNextDeliveryAcknowledgment()
	}
	var preconnectionNoticeID string
	if scenario == "notice_uncertainty_readback" {
		preconnectionNoticeID = onlyPublicChannelNoticeID(t, endpoint+"/v1/rpc", "")
		channelUncertaintySummaryEntry(t, provider)
	}
	if scenario == "delivery_loss_resend" || scenario == "notice_uncertainty_readback" {
		deadline := time.Now().Add(15 * time.Second)
		for provider.Delivery(1) == nil {
			if time.Now().After(deadline) {
				t.Fatal("initial card delivery did not settle before notice loss probe")
			}
			time.Sleep(20 * time.Millisecond)
		}
		time.Sleep(250 * time.Millisecond)
		provider.LoseNextDeliveryAcknowledgment()
	}
	callbackURL, signing, _ := provider.Registration()
	var restartInteraction func() (string, string)
	if retainedInteraction {
		restartInteraction = func() (string, string) {
			if code := process.stop(); code != 0 {
				t.Fatalf("interaction restart exited %d: %s", code, process.outputString())
			}
			process = startServeRuntimeTestProcess(t, opts)
			process.waitForReadyLine()
			callback, secret, _ := provider.Registration()
			return callback, secret
		}
	}
	if scenario == "action_pages" {
		proveChannelPagedCardActions(t, provider, callbackURL, signing)
		return
	}
	update := map[string]any{"update_id": time.Now().UnixMilli(), "message": map[string]any{"message_id": 9101, "from": map[string]any{"id": 7000}, "chat": map[string]any{"id": 1001, "type": "private"}, "text": inputText}}
	if scenario == "verdict" || scenario == "verdict_ack_loss" || scenario == "required_input" || scenario == "invalid_input" || scenario == "edit_loss_resend" || scenario == "ordered_input" || scenario == "cancel_input" || scenario == "skip_input" || scenario == "draft_chooser" || scenario == "quoted_two" {
		cardMessageID := 2
		if scenario == "quoted_two" || scenario == "draft_chooser" {
			cardMessageID = cardMessages["telegram-ingress"]
		}
		deadline := time.Now().Add(15 * time.Second)
		for provider.Delivery(cardMessageID-1) == nil {
			if time.Now().After(deadline) {
				t.Fatal("card was not delivered before callback")
			}
			time.Sleep(20 * time.Millisecond)
		}
		cardMessage := provider.Delivery(cardMessageID - 1)
		markup, ok := cardMessage["reply_markup"].(map[string]any)
		if !ok {
			t.Fatalf("card has no callback controls: %v", cardMessage)
		}
		rows, ok := markup["inline_keyboard"].([]any)
		if !ok || len(rows) == 0 {
			t.Fatalf("card has no callback rows: %v", markup)
		}
		row, ok := rows[0].([]any)
		if !ok || len(row) == 0 {
			t.Fatalf("card has no first callback row: %v", rows)
		}
		control, ok := row[0].(map[string]any)
		if !ok || fmt.Sprint(control["callback_data"]) == "" {
			t.Fatalf("card has no callback token: %v", row)
		}
		update = map[string]any{"update_id": time.Now().UnixMilli(), "callback_query": map[string]any{"id": "callback-9102", "from": map[string]any{"id": 7000}, "message": map[string]any{"message_id": cardMessageID, "chat": map[string]any{"id": 1001, "type": "private"}}, "data": control["callback_data"]}}
		if scenario == "verdict_ack_loss" {
			provider.LoseNextCallbackAcknowledgment()
		}
		if scenario == "edit_loss_resend" {
			provider.LoseNextEditAcknowledgment()
		}
	}
	requestBody, err := json.Marshal(update)
	if err != nil {
		t.Fatal(err)
	}
	request, err := http.NewRequestWithContext(context.Background(), http.MethodPost, callbackURL, strings.NewReader(string(requestBody)))
	if err != nil {
		t.Fatal(err)
	}
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-Telegram-Bot-Api-Secret-Token", signing)
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	responseBody, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	if response.StatusCode != http.StatusAccepted {
		t.Fatalf("business text admission status=%d body=%s", response.StatusCode, responseBody)
	}
	var admitted struct {
		EventNames []string `json:"event_names"`
	}
	if err := json.Unmarshal(responseBody, &admitted); err != nil {
		t.Fatal(err)
	}
	if scenario == "view_full" {
		if len(admitted.EventNames) == 0 {
			t.Fatal("view-full source did not enter the business flow")
		}
		proveChannelViewFullCallbackPages(t, provider, callbackURL, signing, endpoint+"/v1/rpc")
		return
	}
	if scenario == "notice_ack" {
		if len(admitted.EventNames) == 0 {
			t.Fatal("notice source did not enter the business flow")
		}
		proveChannelNoticeAcknowledgment(t, provider, callbackURL, signing, endpoint+"/v1/rpc")
		return
	}
	if scenario == "delivery_loss_resend" {
		if len(admitted.EventNames) == 0 {
			t.Fatal("lost-response notice source did not enter the business flow")
		}
		proveChannelManualResendAfterLostNotice(t, provider, callbackURL, signing, observation)
		return
	}
	if scenario == "notice_uncertainty_readback" {
		if len(admitted.EventNames) == 0 {
			t.Fatal("uncertain notice source did not enter the business flow")
		}
		proveChannelUncertainNoticeReadback(t, provider, backend, observerDSN, endpoint+"/v1/rpc", preconnectionNoticeID, observation, func() {
			if code := process.stop(); code != 0 {
				t.Fatalf("uncertain notice restart exited %d: %s", code, process.outputString())
			}
			process = startServeRuntimeTestProcess(t, opts)
			process.waitForReadyLine()
		})
		return
	}
	if scenario == "edit_loss_resend" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("lost prompt edit callback escaped into business events: %v", admitted.EventNames)
		}
		proveChannelEditLossResendQuotedInput(t, provider, callbackURL, signing, observation)
		return
	}
	if scenario == "required_input" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelRequiredInputText(t, provider, callbackURL, signing)
		return
	}
	if scenario == "invalid_input" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("typed draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelInvalidInputText(t, provider, callbackURL, signing)
		return
	}
	if scenario == "ordered_input" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("ordered draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelOrderedInputText(t, provider, callbackURL, signing, restartInteraction)
		return
	}
	if scenario == "cancel_input" || scenario == "skip_input" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelInputControl(t, provider, callbackURL, signing, scenario)
		return
	}
	if scenario == "draft_chooser" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelBareInputChooser(t, provider, callbackURL, signing, cardMessages["telegram-stopped"], cardMessages["telegram-ingress"], restartInteraction)
		return
	}
	if scenario == "quoted_two" {
		if len(admitted.EventNames) != 0 {
			t.Fatalf("quoted-draft begin leaked business events: %v", admitted.EventNames)
		}
		proveChannelQuotedTwoDrafts(t, provider, callbackURL, signing, cardMessages["telegram-stopped"], cardMessages["telegram-ingress"])
		return
	}
	if (nativeInboxScenario || scenario == "verdict" || scenario == "verdict_ack_loss") && len(admitted.EventNames) != 0 {
		t.Fatalf("native inbox entry leaked into business events: %v", admitted.EventNames)
	}
	if !nativeInboxScenario && scenario != "verdict" && scenario != "verdict_ack_loss" && len(admitted.EventNames) == 0 {
		t.Fatalf("ordinary text was consumed without a business event: status=%d events=%v", response.StatusCode, admitted.EventNames)
	}
	deadline := time.Now().Add(15 * time.Second)
	for {
		if (scenario == "verdict" || scenario == "verdict_ack_loss") && len(provider.Acknowledgments()) > 0 && len(provider.Edits()) > 0 {
			if scenario == "verdict_ack_loss" {
				time.Sleep(2300 * time.Millisecond)
				if got := len(provider.Acknowledgments()); got != 1 {
					t.Fatalf("lost callback acknowledgment was sent %d times", got)
				}
			}
			return
		}
		for index := 1; ; index++ {
			delivery := provider.Delivery(index)
			if delivery == nil {
				break
			}
			message := fmt.Sprint(delivery["text"])
			if nativeInboxScenario && fmt.Sprint(delivery["chat_id"]) == "1001" && strings.HasPrefix(message, "Inbox\nUnread notices: ") && strings.Contains(message, "Retire service") {
				if scenario == "inbox_restart" {
					time.Sleep(time.Second)
					_, after := provider.Counts()
					if after != preRestartDeliveries+1 {
						t.Fatalf("served restart resent a card or lost inbox response: before=%d after=%d", preRestartDeliveries, after)
					}
				}
				if scenario == "inbox_loss" {
					_, before := provider.Counts()
					time.Sleep(2500 * time.Millisecond)
					_, after := provider.Counts()
					if after != before {
						t.Fatalf("uncertain native inbox response was resent: before=%d after=%d", before, after)
					}
				}
				return
			}
			if fmt.Sprint(delivery["chat_id"]) == "1001" && strings.Contains(message, "ordinary business text") {
				if scenario == "notice" && !strings.Contains(message, "Observed ordinary business text") {
					continue
				}
				if !nativeInboxScenario {
					return
				}
			}
		}
		if time.Now().After(deadline) {
			t.Fatalf("%s flow did not answer %q; deliveries=%v acknowledgments=%v edits=%v", scenario, inputText, provider.Delivery(1), provider.Acknowledgments(), provider.Edits())
		}
		time.Sleep(20 * time.Millisecond)
	}
}

