	}
	if change == "rebind" {
		for attempt := 0; attempt < 2; attempt++ {
			postObjectChannelFact(t, p, "authority-old-choice", map[string]any{"token": token, "cursor": "authority-old-choice", "message": map[string]any{"id": chooser}})
		}
