	if err := func() error {
		var err error
		decisions, err = channelAnchorStorageObservation(t, h).CountEventNameStorage(context.Background(), "mailbox.card_decided")
		return err
	}(); err != nil || decisions != 0 {
		t.Fatalf("obsolete authority decided a card: %d %v", decisions, err)
	}
