	installed := p.calls["/v2/install"]
	var command string
	if len(installed) == 1 {
		commands, _ := installed[0]["commands"].([]any)
		if len(commands) == 1 {
			row, _ := commands[0].(map[string]any)
			command, _ = row["command"].(string)
		}
	}
