func proveObjectChannelRebindRetirement(t *testing.T, h *channelOnboardingE2EHarness, db *sql.DB, p *objectChannelProvider, scope, oldCommand, oldOperation string) {
	t.Helper()
	var begun channelonboarding.Result
	requireServedJSONRPCResult(t, h.rpcEndpoint(), "channel.onboarding_start", map[string]any{"provider": "mock", "verb": "rebind", "provider_credential": "object-provider-secret", "save_proof": true, "client_language": "fr"}, &begun)
	if begun.IdentityOperation == nil {
		t.Fatalf("object rebind has no ceremony: %+v", begun)
	}
	p.mu.Lock()
	callback, signing := p.callback, p.signing
	p.mu.Unlock()
	objectChannelIngress(t, callback, signing, "rebind-claim", map[string]any{"text": begun.IdentityOperation.Challenge, "principal": "operator-a", "room": "queue-b", "scope": scope, "message": map[string]any{"id": "rebind-claim"}})
	claimed := getChannelOnboardingRPC(t, h, begun.Operation.OperationID)
	if claimed.IdentityOperation == nil || claimed.IdentityOperation.State != "awaiting_confirmation" {
		t.Fatalf("object rebind claim unavailable: %+v", claimed)
	}
	var result map[string]any
	requireServedJSONRPCResult(t, h.rpcEndpoint(), "channel.confirm", map[string]any{"operation_id": claimed.IdentityOperation.OperationID, "expected_revision": claimed.IdentityOperation.Revision, "approve": true}, &result)
	ready := retryChannelOnboardingRPC(t, h, begun.Operation.OperationID, "")
	if ready.Readiness == nil || !ready.Readiness.Ready {
		t.Fatalf("object rebind not READY: %+v", ready)
	}
	waitObjectNativeQualification(t, h, begun.Operation.OperationID)
	successorIntent := channeldelivery.IntentObservationQuery{Provider: ready.Operation.Provider, InterfaceKey: ready.Operation.Interface.Key()}
	install := "/v2/install"
	if scope == "shared" {
		install += "_shared"
	}
	p.mu.Lock()
	var command string
	for _, call := range p.calls[install] {
		if call["queue"] == "queue-b" {
			commands, _ := call["commands"].([]any)
			if len(commands) == 1 {
				row, _ := commands[0].(map[string]any)
				command, _ = row["command"].(string)
			}
		}
	}
	before := len(p.deliveries)
	callback, signing = p.callback, p.signing
	p.mu.Unlock()
	if command == "" {
		t.Fatal("rebind did not install the new object destination")
	}
	objectChannelIngress(t, callback, signing, "old-native", map[string]any{"text": "/" + oldCommand, "principal": "operator-a", "room": "queue-a", "scope": scope, "message": map[string]any{"id": "old-native"}, "entry": map[string]any{"reference": oldCommand, "address": "mock_bot"}})
	waitObjectChannelDisposition(t, p.intentReader, objectIntentQuery(successorIntent, channeldelivery.IntentText, "old-native"), "entry_rejected")
	objectChannelIngress(t, callback, signing, "new-native", map[string]any{"text": "/" + command, "principal": "operator-a", "room": "queue-b", "scope": scope, "message": map[string]any{"id": "new-native"}, "entry": map[string]any{"reference": command, "address": "mock_bot"}})
	waitObjectChannelDisposition(t, p.intentReader, objectIntentQuery(successorIntent, channeldelivery.IntentText, "new-native"), "entry")
	p.mu.Lock()
	for _, delivery := range p.deliveries[before:] {
		if delivery["queue"] != "queue-b" {
			p.mu.Unlock()
			t.Fatalf("rebind sent authorized output to obsolete destination: %#v", delivery)
		}
	}
	p.mu.Unlock()
	var retained string
	if err := db.QueryRow(`SELECT conversation_reference FROM connected_channel_activations WHERE operation_id=$1`, oldOperation).Scan(&retained); err != nil || retained != `{"room":"queue-a"}` {
		t.Fatalf("rebind changed retained predecessor source: %s %v", retained, err)
	}
	requireServedJSONRPCResult(t, h.rpcEndpoint(), "channel.unbind", map[string]any{"interface": ready.Operation.Interface.Selector, "expected_revision": ready.Binding.Revision, "idempotency_key": "object-unbind"}, &result)
	var current int
	if err := db.QueryRow(`SELECT COUNT(*) FROM connected_channel_activations WHERE status='current'`).Scan(&current); err != nil || current != 0 {
		t.Fatalf("unbind retained execution authority: %d %v", current, err)
	}
	closeObjectIntentObservation(t, p)
	h.stop(t)
	h.start(t)
	p.intentReader = openChannelAnchorObservation(t, h)
	retired := getChannelOnboardingRPC(t, h, begun.Operation.OperationID)
	if retired.Readiness != nil && retired.Readiness.Ready {
		t.Fatal("retired object activation became executable on restart")
	}
	p.mu.Lock()
	count := len(p.calls[install])
	p.mu.Unlock()
	if count != 2 {
		t.Fatalf("retirement/restart reinstalled obsolete native setting: %d", count)
	}
}

