					decision := lifecycleDecisionParamsForCard(t, rt.Endpoint, child, "approve")
					refusal := requireServedJSONRPCError(t, h.rpcEndpoint(), "mailbox.decide", decision)
					if refusal.Data["code"] != "SELECTED_FORK_CONTROL_UNSUPPORTED" {
						t.Fatalf("fork acquired ordinary card mutation authority: %+v", refusal)
					}
					for method, args := range map[string]map[string]any{"mailbox.defer": {"card_id": child, "until": time.Now().Add(time.Hour).UTC().Format(time.RFC3339Nano), "idempotency_key": uuid.NewString()}, "mailbox.begin_input": {"card_id": child, "verdict": "reject", "observed_content_hash": decision["observed_content_hash"], "idempotency_key": uuid.NewString()}, "mailbox.cancel_input": {"card_id": child, "input_draft_id": uuid.NewString(), "idempotency_key": uuid.NewString()}} {
						if err := requireServedJSONRPCError(t, h.rpcEndpoint(), method, args); err.Data["code"] != "SELECTED_FORK_CONTROL_UNSUPPORTED" {
							t.Fatalf("%s did not preserve upstream fork refusal: %+v", method, err)
						}
					}
					childMessage := waitChannelAnchorReceipt(t, channelAnchorStorageObservation(t, h), child)
					childToken, found := telegramCallbackToken(h.provider.Delivery(childMessage-1), "approve")
					if !found || childToken == token {
						t.Fatal("fork delivery reused parent control identity")
					}
					readParent := func() [3]string {
						var state [3]string
						if err := db.QueryRow(`SELECT status,COALESCE(verdict,''),CAST(updated_at AS TEXT) FROM decision_cards WHERE card_id=$1`, card).Scan(&state[0], &state[1], &state[2]); err != nil {
							t.Fatal(err)
						}
						return state
					}
					parentBefore := readParent()
					_, childIntent := postChannelSourceControlObserved(t, callback, signing, intentIdentity, child, childToken, childMessage)
					reader := openChannelAnchorObservation(t, h)
					deadline := time.Now().Add(5 * time.Second)
					for {
						settled, result := observeChannelDisposition(t, reader, childIntent, "unsupported")
						if settled {
							break
						}
						if time.Now().After(deadline) {
							observed, cardErr := channelAnchorStorageObservation(t, h).ReadChannelAnchorDecisionStorage(context.Background(), child)
							status, verdict := observed.Status, observed.Verdict
							var decisions int
							var eventErr error
							decisions, eventErr = channelAnchorStorageObservation(t, h).CountRunNamedEventStorage(context.Background(), fork.ForkRunID, "mailbox.card_decided")
							t.Fatalf("selected-fork callback %+v lacks terminal unsupported disposition: observation=%+v card_status=%s verdict=%s card_err=%v decisions=%d event_err=%v", childIntent, result, status, verdict, cardErr, decisions, eventErr)
						}
						time.Sleep(20 * time.Millisecond)
					}
					if err := reader.Close(); err != nil {
						t.Fatal(err)
					}
					var status string
					if err := func() error {
						observed, err := channelSettlementStorageObservation(t, h).ReadChannelAnchorDecisionStorage(context.Background(), child)
						status = observed.Status
						return err
					}(); err != nil || status != "pending" {
						t.Fatalf("fork callback bypassed selected control refusal: status=%s err=%v", status, err)
					}
					postChannelSourceControl(t, callback, signing, child, childToken, childMessage)
					ordinary := requireServedEventPublishRPCResult(t, h.rpcEndpoint(), map[string]any{"event_name": "work.requested", "bundle_hash": hash, "payload": map[string]any{"seed": true}, "idempotency_key": uuid.NewString()})
					ordinaryCard := waitChannelAnchorCard(t, channelAnchorStorageObservation(t, h), ordinary.RunID, decisioncard.AnchorKindStageGate, "reviews")
					ordinaryMessage := waitChannelAnchorReceipt(t, channelAnchorStorageObservation(t, h), ordinaryCard)
					ordinaryToken, ok := telegramCallbackToken(h.provider.Delivery(ordinaryMessage-1), "approve")
					if !ok {
						t.Fatal("normal run lost decision control")
					}
					postChannelSourceControl(t, callback, signing, ordinaryCard, ordinaryToken, ordinaryMessage)
					waitChannelAnchorDecision(t, channelAnchorStorageObservation(t, h), ordinaryCard)
					waitSelectedChannelDeliverySendsSettled(t, channelSettlementStorageObservation(t, h))
					h.stop(t)
					h.start(t)
					callback, signing, _ = h.provider.Registration()
					postChannelSourceControl(t, callback, signing, child, childToken, childMessage)
					var verdict string
					var events, drafts int
					replayedDecision, decisionErr := channelAnchorStorageObservation(t, h).ReadChannelAnchorDecisionStorage(context.Background(), child)
					status, verdict = replayedDecision.Status, replayedDecision.Verdict
					if err := decisionErr; err != nil || status != "pending" || verdict != "" {
						t.Fatalf("fork replay/restart changed child: %s/%s %v", status, verdict, err)
					}
					{
						var err error
						events, err = channelAnchorStorageObservation(t, h).CountRunNamedEventStorage(context.Background(), fork.ForkRunID, "mailbox.card_decided")
						if err != nil || events != 0 {
							t.Fatalf("fork restart emitted a decision: %d %v", events, err)
						}
					}
					if err := db.QueryRow(`SELECT COUNT(*) FROM decision_card_input_drafts WHERE card_id=$1`, child).Scan(&drafts); err != nil || drafts != 0 {
						t.Fatalf("upstream fork refusal created a draft: %d %v", drafts, err)
					}
					if readParent() != parentBefore {
						t.Fatal("child refusal or normal-run control mutated the frozen parent card")
					}
				}
				if after := readChannelSourceHistory(t, db, card); after != frozen {
					t.Fatal("source lifecycle changed historical receipt/render evidence")
				}
			})
		}
	}
}

